const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => crypto.randomUUID();
const colors = ['sage','midnight','rose','butter','slate','moss'];
const symbols = ['❧','✦','❀','☾','◇','✧'];
const samples = [
 ['우리가 머무는 계절','현대 AU','sage','❧','비가 그친 오후, 익숙한 마음이 다시 문을 두드렸다.'],
 ['별이 잠든 도서관','해리포터 AU','midnight','✦','금지된 서가의 끝에서, 두 사람만 아는 주문이 시작된다.'],
 ['너에게 기우는 봄','캠퍼스 AU','rose','❀','같은 강의실, 다른 계절을 지나 마침내 나란히.'],
 ['달의 뒷면에서','원작 세계관','butter','☾','멀리 돌아온 마음에도 돌아갈 자리는 있다.']
].map(([title,au,color,symbol,description],i)=>({id:'sample-'+i,title,au,couple:'크로네리',color,symbol,description,status:'연재 중',sample:true,updated:0,chapters:[{id:'sample-ch-'+i,title:['비가 그친 오후','서가의 끝에서','새 학기의 첫 문장','돌아오는 길'][i],text:'이 글은 서재와 리더의 분위기를 보여주기 위한 예시입니다. 실제 원고가 아닙니다.\n\n'+description+'\n\n창가에 놓인 책 한 권이 바람에 천천히 펼쳐졌다. 미처 읽지 못한 문장들이 오후의 빛 속에서 조용히 기다리고 있었다.\n\n어쩌면 이야기는 거창한 사건이 아니라, 이렇게 작은 순간에서 시작되는 것인지도 몰랐다.\n\n그는 책갈피를 끼워 둔 페이지를 펼쳤다. 오래전의 문장이 여전히 그 자리에서 그를 맞았다.\n\n“이번에는 끝까지 읽어 볼게.”\n\n그 말은 책을 향한 것이었을까. 창밖을 바라보던 사람은 대답 대신 희미하게 웃었다.',updated:0}]}));
let books=[], user=null, firebase=null, cloudReady=false, authBusy=false, filter='전체', query='', coupleFilter='전체', page='library', currentBook=null, currentChapter=null, saveTimer, cloudTimer, toastTimer, db, pendingEdit=false;
let dirty=new Map(), localWrites=new Set(), cloudWrites=new Set(), syncing=false;
const prefs=JSON.parse(localStorage.getItem('galpi-prefs')||'{"size":19,"line":2,"dark":false}');
const marks=()=>JSON.parse(localStorage.getItem('galpi-marks-'+(user?.uid||'guest'))||'{}');
const storeMarks=v=>localStorage.setItem('galpi-marks-'+(user?.uid||'guest'),JSON.stringify(v));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function status(message){$('#sync-status').textContent=message}
function openDialog(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
function cover(b){return `<div class="cover ${esc(b.color)}"><small>GALPI · ${esc(b.au)}</small><div class="cover-title">${esc(b.title)}</div><div class="cover-symbol">${esc(b.symbol)}</div><div class="cover-bottom">${esc(b.couple)}</div></div>`}
function actual(){return books.filter(b=>!b.sample)}
function displayed(){return books.length?books:samples}
async function initDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('galpi-library',1);r.onupgradeneeded=()=>r.result.createObjectStore('books',{keyPath:'key'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});await loadLocal()}
async function loadLocal(){const key=user?.uid||'guest';const all=await new Promise((res,rej)=>{const r=db.transaction('books').objectStore('books').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});books=all.filter(b=>b.owner===key).map(b=>b.book)}
function putLocal(b,owner=user?.uid||'guest'){const promise=new Promise((res,rej)=>{const t=db.transaction('books','readwrite');t.objectStore('books').put({key:owner+':'+b.id,owner,book:structuredClone(b)});t.oncomplete=res;t.onerror=()=>rej(t.error)});localWrites.add(promise);promise.finally(()=>localWrites.delete(promise)).catch(()=>{});return promise}
function recordDirty(b,ch){dirty.set(b.id+':'+(ch?.id||''),{b:structuredClone(b),ch:ch?structuredClone(ch):null,owner:user?.uid});}
async function saveBook(b,ch){b.updated=Date.now();if(ch)ch.updated=b.updated;try{await putLocal(b);status(user?'기기에 저장 · 동기화 대기':'이 브라우저에 저장됨');if(user){recordDirty(b,ch);clearTimeout(cloudTimer);cloudTimer=setTimeout(syncDirty,1800)}}catch{status('저장 실패 · 백업 필요');toast('기기 저장 공간에 문제가 있어요. 설정에서 원고를 백업해 주세요.')}}
async function syncDirty(){if(!firebase||!user||!cloudReady||syncing||!dirty.size)return;syncing=true;status('동기화 중…');let failed=false;for(const [key,entry] of [...dirty]){if(entry.owner!==user?.uid)continue;const {b,ch}=entry;const p=(async()=>{const {chapters,sample,...meta}=b;await firebase.setDoc(firebase.doc(firebase.db,'users',entry.owner,'galpiSeries',b.id),meta);if(ch)await firebase.setDoc(firebase.doc(firebase.db,'users',entry.owner,'galpiSeries',b.id,'chapters',ch.id),{...ch,order:b.chapters.findIndex(c=>c.id===ch.id)})})();cloudWrites.add(p);try{await p;if(dirty.get(key)===entry)dirty.delete(key)}catch(e){failed=true;status('기기 저장됨 · 클라우드 연결 확인 필요');toast(firebaseError(e));break}finally{cloudWrites.delete(p)}}syncing=false;if(!failed)status(dirty.size?'동기화 대기':'Google 계정에 저장됨');if(!failed&&dirty.size)cloudTimer=setTimeout(syncDirty,1800)}
function firebaseError(e){return ({'auth/unauthorized-domain':'Firebase 인증 설정에 현재 사이트 도메인을 추가해 주세요.','auth/operation-not-allowed':'Firebase Authentication에서 Google 로그인을 활성화해 주세요.','auth/popup-blocked':'팝업이 차단됐어요. 브라우저에서 팝업을 허용해 주세요.','auth/popup-closed-by-user':'로그인 창이 닫혔어요.','permission-denied':'Firestore 보안 규칙을 확인해 주세요. 원고는 이 기기에 저장되어 있어요.','auth/network-request-failed':'네트워크 연결을 확인해 주세요.'})[e.code]||'연결을 완료하지 못했어요. Firebase 설정과 네트워크를 확인해 주세요.'}
async function initFirebase(){try{const base='https://www.gstatic.com/firebasejs/12.4.0/';const [app,auth,fs]=await Promise.all([import(base+'firebase-app.js'),import(base+'firebase-auth.js'),import(base+'firebase-firestore.js')]);const instance=app.initializeApp({apiKey:'AIzaSyB9SWQzJrzxbT1aKquMyqz-Hvd1Ce87xZA',authDomain:'kkyareuk.firebaseapp.com',projectId:'kkyareuk',storageBucket:'kkyareuk.firebasestorage.app',messagingSenderId:'694440030853',appId:'1:694440030853:web:2b3f385d5e88977b20afec'});firebase={...auth,...fs,auth:auth.getAuth(instance),db:fs.getFirestore(instance)};auth.onAuthStateChanged(firebase.auth,async next=>{authBusy=true;$('#app').inert=true;await flush();user=next;cloudReady=false;dirty.clear();await loadLocal();$('#account-name').innerHTML=next?`${esc(next.displayName||'나의 계정')}<small>Google 계정 연결됨</small>`:'Google로 로그인<small>나의 이야기를 안전하게</small>';if(next){status('내 서재 불러오는 중…');try{const snap=await fs.getDocs(fs.collection(firebase.db,'users',next.uid,'galpiSeries'));const remote=await Promise.all(snap.docs.map(async d=>{const chapters=await fs.getDocs(fs.collection(firebase.db,'users',next.uid,'galpiSeries',d.id,'chapters'));return {...d.data(),id:d.id,chapters:chapters.docs.map(c=>({...c.data(),id:c.id})).sort((a,b)=>(a.order||0)-(b.order||0))}}));for(const r of remote){const local=books.find(b=>b.id===r.id);if(!local){books.push(r);await putLocal(r)}else{const merged={...(local.updated>r.updated?local:r),chapters:[...r.chapters]};for(const c of local.chapters){const n=merged.chapters.findIndex(x=>x.id===c.id);if(n<0)merged.chapters.push(c);else if(c.updated>merged.chapters[n].updated)merged.chapters[n]=c}books[books.indexOf(local)]=merged;await putLocal(merged)}}cloudReady=true;for(const b of books){const r=remote.find(x=>x.id===b.id);if(!r||b.updated>r.updated)recordDirty(b);for(const ch of b.chapters){const c=r?.chapters.find(x=>x.id===ch.id);if(!c||ch.updated>c.updated)recordDirty(b,ch)}}status('Google 계정에 연결됨');await syncDirty()}catch(e){status('기기 저장 모드 · 연결 확인 필요');toast(firebaseError(e))}}else status('이 브라우저에 저장');authBusy=false;$('#app').inert=false;route()})}catch{status('오프라인 · 이 브라우저에 저장');toast('Google 연결을 불러오지 못했어요. 기기 저장으로 계속 사용할 수 있습니다.')}}
async function login(){if(!firebase){toast('Google 연결을 준비 중이에요. 잠시 후 다시 눌러 주세요.');return}await flush();try{await firebase.signInWithPopup(firebase.auth,new firebase.GoogleAuthProvider())}catch(e){toast(firebaseError(e))}}
async function flush(){clearTimeout(saveTimer);saveTimer=null;if(pendingEdit&&currentBook&&currentChapter&&page==='edit'){pendingEdit=false;await saveBook(currentBook,currentChapter);}await Promise.allSettled([...localWrites]);void syncDirty()}
function card(b){return `<button class="book-card" data-book="${esc(b.id)}">${cover(b)}<h3>${esc(b.title)}</h3><div class="meta"><span>${esc(b.couple)}</span><span>·</span><span>${esc(b.au)}</span></div><div class="book-progress">${b.chapters.length}화 <span>· ${b.sample?'미리보기 작품':esc(b.status)}</span></div></button>`}
function bindBooks(){$$('[data-book]').forEach(el=>el.onclick=()=>location.hash='series/'+el.dataset.book)}
function $$(s){return [...document.querySelectorAll(s)]}
function library(){const list=displayed().filter(b=>(filter==='전체'||b.au===filter)&&(coupleFilter==='전체'||b.couple===coupleFilter)&&[b.title,b.couple,b.au,b.description].join(' ').toLowerCase().includes(query.toLowerCase()));const all=displayed();$('#app').innerHTML=`<div class="title-row"><div><p class="eyebrow">A LITTLE SPACE FOR YOUR STORIES</p><h1>나의 이야기 서재</h1><p class="sub">좋아하는 두 사람, 끝없이 펼쳐지는 세계.</p></div><button class="btn primary" id="new-series">＋ 새 시리즈</button></div><section class="hero"><div class="hero-copy"><p class="eyebrow">BETWEEN THE PAGES</p><h2>어떤 세계에서든,<br>다시 만나는 우리.</h2><p class="sub">마음에 담아둔 이야기를 한 권씩 꺼내 보세요.</p><button class="btn small" id="hero-read">${localStorage.getItem('galpi-last-'+(user?.uid||'guest'))?'이어서 읽기':'첫 이야기 펼치기'} <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="mini-book">우리가<br>머무는 계절<small>A STORY OF US</small></div><div class="mini-book">별이 잠든<br>도서관<small>ANOTHER UNIVERSE</small></div><span class="star">✧</span></div></section><div class="section-heading"><h2>책장 <span class="count">${actual().length?actual().length+'개의 시리즈':'미리보기'}</span></h2><button class="text-btn" id="sort">최근 수정순 ↕</button></div><div class="filters">${['전체',...new Set(all.map(b=>b.au))].map(a=>`<button class="chip ${filter===a?'active':''}" data-filter="${esc(a)}">${esc(a)}</button>`).join('')}<input class="search" id="search" aria-label="제목, 커플링, AU 검색" placeholder="⌕  제목, 커플링, AU 검색" value="${esc(query)}"></div>${!books.length?'<p class="sub">아래 작품은 디자인 미리보기예요. 새 시리즈를 만들면 나만의 책장이 시작됩니다.</p>':''}${coupleFilter!=='전체'?`<p class="sub">${esc(coupleFilter)} <button class="text-btn" id="clear-couple">분류 해제 ×</button></p>`:''}<div class="books">${list.sort((a,b)=>b.updated-a.updated).map(card).join('')||'<div class="empty">아직 이 세계의 이야기가 없어요.<br>새 시리즈로 첫 문장을 시작해 보세요.</div>'}</div>`;bindBooks();$('#new-series').onclick=newSeries;$$('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;library()});$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;library();$('#search').focus();$('#search').setSelectionRange(pos,pos)};$('#sort').onclick=()=>{toast('최근 수정한 시리즈부터 표시하고 있어요.')};$('#clear-couple')?.addEventListener('click',()=>{coupleFilter='전체';library()});$('#hero-read').onclick=()=>{const last=localStorage.getItem('galpi-last-'+(user?.uid||'guest'));location.hash=last||'series/'+displayed()[0].id}}
function newSeries(){openDialog(`<h2>새로운 세계의 첫 페이지</h2><p>커플링은 이야기의 중심, AU는 그들이 만나는 세계예요.</p><form id="series-form"><label class="field">시리즈 제목<input name="title" required maxlength="80" placeholder="예: 우리가 머무는 계절"></label><label class="field">커플링<input name="couple" required maxlength="50" value="크로네리"></label><label class="field">AU · 세계관<input name="au" required maxlength="50" placeholder="예: 현대 AU, 해리포터 AU" list="au-list"><datalist id="au-list"><option>현대 AU</option><option>해리포터 AU</option><option>원작 세계관</option><option>캠퍼스 AU</option></datalist></label><label class="field">한 줄 소개<textarea name="description" maxlength="500" placeholder="이 세계에서 두 사람은 어떻게 만날까요?"></textarea></label><label class="field">표지 색<select name="color">${colors.map((c,i)=>`<option value="${c}">${['세이지 그린','미드나이트 블루','더스티 로즈','버터 크림','미스트 블루','포레스트 그린'][i]}</option>`).join('')}</select></label><div class="dialog-actions"><button type="button" class="btn" data-close>취소</button><button class="btn primary">시리즈 만들기</button></div></form>`);$('#series-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));for(const k of ['title','couple','au'])if(!f[k].trim()){toast('제목, 커플링, 세계관을 입력해 주세요.');return}const b={...f,id:uid(),symbol:symbols[colors.indexOf(f.color)],status:'연재 중',updated:Date.now(),chapters:[]};books.push(b);await saveBook(b);$('#modal').close();location.hash='series/'+b.id}}
function series(b){$('#app').innerHTML=`<a href="#library" class="back">← 서재로 돌아가기</a><div class="detail">${cover(b)}<div><div class="meta"><span class="tag">${esc(b.couple)}</span><span>×</span><span class="tag">${esc(b.au)}</span></div><h1>${esc(b.title)}</h1><p class="sub">${esc(b.description)||'아직 쓰이지 않은 이야기를 기다리고 있어요.'}</p><div class="meta">${b.chapters.length}화 · ${esc(b.status)}${b.sample?' · 미리보기 작품':''}</div><div class="actions"><button class="btn primary" id="start-read" ${!b.chapters.length?'disabled':''}>이야기 읽기 ↗</button>${!b.sample?'<button class="btn" id="add-chapter">＋ 회차 쓰기</button><button class="btn small" id="edit-series">정보 수정</button>':''}</div></div></div><div class="section-heading"><h2>이야기의 목차</h2><span class="sub">총 ${b.chapters.reduce((s,c)=>s+Array.from(c.text).length,0).toLocaleString()}자</span></div>${b.chapters.map((c,i)=>`<div class="chapter"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><button class="text-btn chapter-info" data-read="${c.id}"><strong>${esc(c.title)}</strong><small>${Array.from(c.text).length.toLocaleString()}자 · 약 ${Math.max(1,Math.ceil(c.text.length/500))}분</small></button>${!b.sample?`<button class="btn small" data-edit="${c.id}">편집</button>`:'<span class="meta">미리보기</span>'}</div>`).join('')||'<div class="empty">목차가 아직 비어 있어요.<br>첫 회차를 쓰거나 Claude에서 쓴 원고를 붙여 넣어 보세요.</div>'}`;$('#start-read').onclick=()=>location.hash=`read/${b.id}/${b.chapters[0].id}`;$('#add-chapter')?.addEventListener('click',async()=>{const c={id:uid(),title:`${b.chapters.length+1}화. 새로운 이야기`,text:'',updated:Date.now()};b.chapters.push(c);await saveBook(b,c);location.hash=`edit/${b.id}/${c.id}`});$$('[data-read]').forEach(el=>el.onclick=()=>location.hash=`read/${b.id}/${el.dataset.read}`);$$('[data-edit]').forEach(el=>el.onclick=()=>location.hash=`edit/${b.id}/${el.dataset.edit}`);$('#edit-series')?.addEventListener('click',()=>editSeries(b))}
function editSeries(b){openDialog(`<h2>시리즈 정보</h2><form id="edit-meta"><label class="field">제목<input name="title" required maxlength="80" value="${esc(b.title)}"></label><label class="field">커플링<input name="couple" required maxlength="50" value="${esc(b.couple)}"></label><label class="field">AU<input name="au" required maxlength="50" value="${esc(b.au)}"></label><label class="field">소개<textarea name="description" maxlength="500">${esc(b.description)}</textarea></label><label class="field">연재 상태<select name="status">${['연재 중','완결','잠시 쉬는 중'].map(s=>`<option ${s===b.status?'selected':''}>${s}</option>`).join('')}</select></label><div class="dialog-actions"><button type="button" class="btn" data-close>취소</button><button class="btn primary">저장</button></div></form>`);$('#edit-meta').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(['title','couple','au'].some(k=>!data[k].trim()))return toast('빈 항목을 채워 주세요.');Object.assign(b,data);await saveBook(b);$('#modal').close();series(b)}}
function edit(b,c){if(b.sample){toast('미리보기 작품은 편집할 수 없어요. 새 시리즈를 만들어 주세요.');location.hash='series/'+b.id;return}$('#app').innerHTML=`<div class="editor-head"><a href="#series/${b.id}" class="back" style="margin:0">← ${esc(b.title)}</a><div class="actions" style="margin:0"><button class="btn small" id="import-text">TXT 가져오기</button><a class="btn small" href="#read/${b.id}/${c.id}">읽기 미리보기</a></div></div><p class="eyebrow">WRITING ROOM · ${esc(b.couple)} × ${esc(b.au)}</p><input class="editor-title" id="chapter-title" aria-label="회차 제목" maxlength="100" value="${esc(c.title)}"><textarea class="editor-body" id="manuscript" aria-label="소설 원고" maxlength="180000" placeholder="첫 문장을 써 보세요. Claude에서 쓴 이야기를 붙여 넣어도 좋아요." spellcheck="false">${esc(c.text)}</textarea><div class="editor-stats"><span id="char-count"></span><span id="no-space"></span><span id="draft-status">자동 저장 준비됨</span></div>`;const update=()=>{$('#char-count').textContent=Array.from(c.text).length.toLocaleString()+'자 (공백 포함)';$('#no-space').textContent=Array.from(c.text.replace(/\s/g,'')).length.toLocaleString()+'자 (공백 제외)'};update();const changed=()=>{pendingEdit=true;c.title=$('#chapter-title').value;c.text=$('#manuscript').value;update();$('#draft-status').textContent='저장 중…';clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{saveTimer=null;pendingEdit=false;await saveBook(b,c);if($('#draft-status'))$('#draft-status').textContent=$('#sync-status').textContent.startsWith('저장 실패')?'저장 실패 · 백업 필요':'기기에 저장됨'},600)};$('#chapter-title').oninput=changed;$('#manuscript').oninput=changed;$('#import-text').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.txt,text/plain';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>720000)return toast('회차당 18만 자 이하의 TXT 파일을 사용해 주세요.');const text=await file.text();if(text.length>180000)return toast('원고를 여러 회차로 나눠 주세요. 회차당 최대 18만 자입니다.');if(c.text&&!confirm('현재 회차 원고를 가져온 파일로 바꿀까요?'))return;$('#manuscript').value=text;changed()};input.click()}}
function read(b,c){localStorage.setItem('galpi-last-'+(user?.uid||'guest'),`read/${b.id}/${c.id}`);const m=marks(),key=b.id+'/'+c.id,index=b.chapters.indexOf(c);$('#app').innerHTML=`<div class="reader-toolbar"><a href="#series/${b.id}" class="btn small">← 목차</a><span class="meta">${index+1} / ${b.chapters.length}화</span><div><button class="btn small" id="bookmark">${m[key]?'◆ 저장됨':'◇ 책갈피'}</button> <button class="btn small" id="reader-options">가 Aa</button></div></div><div class="reader-settings" id="reader-settings" hidden><label>글자 <input type="range" id="font-size" min="15" max="30" value="${prefs.size}"></label><label>줄 간격 <input type="range" id="line-height" min="1.5" max="2.8" step=".1" value="${prefs.line}"></label><button class="btn small" id="theme">밤 / 낮</button></div><article class="reader"><p class="eyebrow">${esc(b.title)} · ${index+1}화</p><h1>${esc(c.title)}</h1><div class="reader-text">${esc(c.text)||'아직 쓰인 문장이 없어요. 집필실에서 이야기를 시작해 보세요.'}</div><div class="reader-bottom">${index?`<a class="btn" href="#read/${b.id}/${b.chapters[index-1].id}">← 이전 화</a>`:'<span></span>'}${index<b.chapters.length-1?`<a class="btn primary" href="#read/${b.id}/${b.chapters[index+1].id}">다음 화 →</a>`:`<a class="btn" href="#series/${b.id}">목차로 돌아가기</a>`}</div></article>`;$('#reader-settings').style.display='none';$('#reader-options').onclick=()=>{$('#reader-settings').style.display=$('#reader-settings').style.display==='none'?'flex':'none'};$('#bookmark').onclick=()=>{const current=marks();if(current[key])delete current[key];else current[key]={title:c.title,series:b.title};storeMarks(current);$('#bookmark').textContent=current[key]?'◆ 저장됨':'◇ 책갈피'};$('#font-size').oninput=e=>{prefs.size=+e.target.value;applyPrefs()};$('#line-height').oninput=e=>{prefs.line=+e.target.value;applyPrefs()};$('#theme').onclick=()=>{prefs.dark=!prefs.dark;applyPrefs()};applyPrefs();const position=Number(localStorage.getItem('galpi-position-'+(user?.uid||'guest')+'-'+key)||0);requestAnimationFrame(()=>scrollTo(0,position))}
function applyPrefs(){document.body.classList.toggle('dark',page==='read'&&prefs.dark);document.documentElement.style.setProperty('--reader-size',prefs.size+'px');document.documentElement.style.setProperty('--reader-line',prefs.line);localStorage.setItem('galpi-prefs',JSON.stringify(prefs))}
function worlds(){const all=displayed(),pairs=['전체',...new Set(all.map(b=>b.couple))],aus=[...new Set(all.map(b=>b.au))];$('#app').innerHTML=`<p class="eyebrow">SAME LOVE, DIFFERENT UNIVERSES</p><h1>세계관 지도</h1><p class="sub">같은 두 사람을, 다른 세계에서 만나 보세요.<br>커플링과 세계관을 조합하면 나만의 이야기 지도가 됩니다.</p><div class="world-axis"><select id="world-couple" aria-label="커플링 선택">${pairs.map(p=>`<option ${p===coupleFilter?'selected':''}>${esc(p)}</option>`).join('')}</select><span>×</span><span class="sub">그들이 만나는 세계</span></div><div class="world-grid">${aus.map((a,i)=>{const count=all.filter(b=>b.au===a&&(coupleFilter==='전체'||b.couple===coupleFilter)).length;return `<button class="world" data-au="${esc(a)}"><span class="symbol">${symbols[i%symbols.length]}</span><h3>${esc(a)}</h3><p>${count}개의 시리즈 <span style="float:right">↗</span></p></button>`}).join('')}</div>`;$('#world-couple').onchange=e=>{coupleFilter=e.target.value;worlds()};$$('[data-au]').forEach(el=>el.onclick=()=>{filter=el.dataset.au;query='';location.hash='library'})}
function writing(){const list=actual();$('#app').innerHTML=`<div class="title-row"><div><p class="eyebrow">ONE SENTENCE AT A TIME</p><h1>나의 집필실</h1><p class="sub">떠오른 문장을 붙잡아 두는 시간.</p></div><button class="btn primary" id="new-series">＋ 새 시리즈</button></div>${list.length?list.map(b=>`<div class="saved-row"><div><a href="#series/${b.id}">${esc(b.title)}</a><p class="meta">${esc(b.couple)} × ${esc(b.au)} · ${b.chapters.length}화</p></div><a class="btn small" href="#${b.chapters.length?'edit/'+b.id+'/'+b.chapters.at(-1).id:'series/'+b.id}">이어서 쓰기 ↗</a></div>`).join(''):'<div class="empty">아직 집필 중인 작품이 없어요.<br>새 시리즈를 만들고, 첫 회차를 시작해 보세요.</div>'}`;$('#new-series').onclick=newSeries}
function bookmarks(){const list=Object.entries(marks()).filter(([key])=>{const [b,c]=key.split('/');return displayed().some(x=>x.id===b&&x.chapters.some(ch=>ch.id===c))});$('#app').innerHTML=`<p class="eyebrow">PAGES TO RETURN TO</p><h1>다시 펼칠 이야기</h1><p class="sub">책갈피를 꽂아 둔 회차를 모았어요.</p>${list.map(([key,m])=>`<a class="saved-row" href="#read/${key}"><div>${esc(m.title)}<p class="meta">${esc(m.series)}</p></div><span>↗</span></a>`).join('')||'<div class="empty">읽기 화면에서 ◇ 책갈피를 눌러 보세요.</div>'}`}
function exportBooks(){const blob=new Blob([JSON.stringify({format:'galpi',version:1,books:actual()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='galpi-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function settings(){openDialog(`<h2>나의 서재 설정</h2><p>${user?'Google 계정: '+esc(user.email):'현재 이 브라우저에 원고를 저장하고 있어요. Google로 로그인하면 계정별 서재를 이용할 수 있습니다.'}</p><div class="notice">${user?'클라우드 저장은 Firebase 인증·Firestore 설정이 완료되어야 작동합니다. 화면 위 저장 상태를 확인해 주세요.':'브라우저 데이터를 지우기 전에 원고를 백업해 주세요. 로그인 전 쓴 원고는 로그인한 뒤 백업 가져오기로 옮길 수 있어요.'}</div><div class="actions"><button class="btn" id="google-action">${user?'로그아웃':'Google로 로그인'}</button><button class="btn" id="backup">원고 백업</button><button class="btn" id="restore">백업 가져오기</button></div><p style="margin-top:20px">회차당 최대 18만 자 · 자동 저장 0.6초<br>책갈피와 읽기 위치, 글꼴 설정은 이 기기에 보관합니다.</p><div class="dialog-actions"><button class="btn primary" data-close>닫기</button></div>`);$('#google-action').onclick=async()=>{await flush();if(user){if(dirty.size&&!confirm('아직 클라우드에 저장되지 않은 원고가 있어요. 기기에는 보관됩니다. 로그아웃할까요?'))return;await firebase.signOut(firebase.auth)}else await login();$('#modal').close()};$('#backup').onclick=exportBooks;$('#restore').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>30000000)throw Error();const data=JSON.parse(await file.text());if(data.format!=='galpi'||!Array.isArray(data.books))throw Error();const clean=data.books.map(b=>{if(typeof b.title!=='string'||typeof b.couple!=='string'||typeof b.au!=='string'||!Array.isArray(b.chapters))throw Error();return {id:uid(),title:b.title.slice(0,80),couple:b.couple.slice(0,50),au:b.au.slice(0,50),description:String(b.description||'').slice(0,500),color:colors.includes(b.color)?b.color:'sage',symbol:symbols.includes(b.symbol)?b.symbol:'❧',status:['연재 중','완결','잠시 쉬는 중'].includes(b.status)?b.status:'연재 중',updated:Date.now(),chapters:b.chapters.map(c=>{if(typeof c.text!=='string'||c.text.length>180000||typeof c.title!=='string')throw Error();return {id:uid(),title:c.title.slice(0,100),text:c.text,updated:Date.now()}})}});for(const b of clean){books.push(b);await saveBook(b);for(const c of b.chapters)if(user)recordDirty(b,c)}await syncDirty();$('#modal').close();route();toast(clean.length+'개 시리즈를 새 사본으로 가져왔어요.')}catch{toast('갈피 백업 파일인지 확인해 주세요. 회차는 최대 18만 자입니다.')}};input.click()}}
let routeSequence=0;
async function route(){if(authBusy)return;const seq=++routeSequence;await flush();if(seq!==routeSequence)return;const [next,bid,cid]=location.hash.slice(1).split('/');page=next||'library';currentBook=displayed().find(b=>b.id===bid);currentChapter=currentBook?.chapters.find(c=>c.id===cid);document.body.classList.remove('dark');$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||a.dataset.nav==='library'&&['series','read'].includes(page)||a.dataset.nav==='writing'&&page==='edit'));scrollTo(0,0);if(['series','read','edit'].includes(page)&&(!currentBook||(page!=='series'&&!currentChapter))){$('#app').innerHTML='<div class="empty">이 이야기를 찾을 수 없어요.<br><a href="#library">서재로 돌아가기 →</a></div>';return}if(page==='series')series(currentBook);else if(page==='edit')edit(currentBook,currentChapter);else if(page==='read')read(currentBook,currentChapter);else if(page==='worlds')worlds();else if(page==='writing')writing();else if(page==='bookmarks')bookmarks();else library()}
$('#account').onclick=()=>user?settings():login();$('#settings').onclick=settings;window.addEventListener('hashchange',route);let scrollTimer;window.addEventListener('scroll',()=>{if(page!=='read'||!currentBook||!currentChapter)return;const key='galpi-position-'+(user?.uid||'guest')+'-'+currentBook.id+'/'+currentChapter.id;const pos=scrollY;clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>localStorage.setItem(key,String(pos)),200)},{passive:true});window.addEventListener('beforeunload',e=>{if(pendingEdit&&page==='edit'){clearTimeout(saveTimer);saveTimer=null;putLocal(currentBook).catch(()=>{});}if(localWrites.size||dirty.size){e.preventDefault();e.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(document.hidden)flush()});window.addEventListener('online',()=>{if(cloudReady)syncDirty()});
try{await initDB();await route();initFirebase()}catch{status('기기 저장 사용 불가');$('#app').innerHTML='<div class="empty">브라우저의 저장소를 열 수 없어요. 일반 브라우저 창에서 다시 열어 주세요.</div>'}
